  @override
  String get legalDataConsentNeverUsedBody =>
      'ഓപ്റ്റ്-ഇൻ ഉൾപ്പെടെ ഒരു സാഹചര്യത്തിലും AI പരിശീലനത്തിനായി ഇനിപ്പറയുന്ന ഡാറ്റ ഒരിക്കലും ഉപയോഗിക്കില്ല: (എ) ബില്ലിംഗ് വിവരങ്ങളും പേയ്‌മെൻ്റ് കാർഡ് ഡാറ്റയും; (ബി) മുഴുവൻ ക്ലയൻ്റ് പേരുകൾ, ദേശീയ ഐഡി നമ്പറുകൾ, പാസ്‌പോർട്ട് നമ്പറുകൾ അല്ലെങ്കിൽ പൂർണ്ണമായ അജ്ഞാതവൽക്കരണം കൂടാതെ ബയോമെട്രിക് ഡാറ്റ; (സി) പ്രിവിലേജ് ഹോൾഡർ വ്യക്തമായ രേഖാമൂലമുള്ള സമ്മതം നൽകുന്നില്ലെങ്കിൽ നിയമപരമായ പ്രൊഫഷണൽ പ്രത്യേകാവകാശത്താൽ പരിരക്ഷിക്കപ്പെട്ട ആശയവിനിമയങ്ങൾ; (ഡി) നിയമപരമായ ഹോൾഡിന് അല്ലെങ്കിൽ സജീവമായ വ്യവഹാരത്തിന് വിധേയമായ ഡാറ്റ; (ഇ) ആരോഗ്യ അല്ലെങ്കിൽ മെഡിക്കൽ ഡാറ്റ; (എഫ്) 18 വയസ്സിന് താഴെയുള്ള ഉപയോക്താക്കളുടെ ഡാറ്റ.';

