  @override
  String get legalDataConsentWhatIsTrainingBody =>
      'ഈ സന്ദർഭത്തിലെ AI പരിശീലനം അർത്ഥമാക്കുന്നത് - അജ്ഞാതവൽക്കരണത്തിനും വ്യാജനാമകരണത്തിനും ശേഷം - കുടയുടെ സവിശേഷതകൾ ശക്തിപ്പെടുത്തുന്ന AI മോഡലുകളുടെ കൃത്യതയോ പ്രസക്തിയോ സുരക്ഷയോ മെച്ചപ്പെടുത്തുന്നതിന് നിങ്ങളുടെ ഡാറ്റ ഉപയോഗിക്കുക എന്നതാണ്. ഏതെങ്കിലും മൂന്നാം കക്ഷിയുമായി തിരിച്ചറിയാവുന്ന ക്ലയൻ്റ് ഡാറ്റ പങ്കിടുക എന്നല്ല ഇതിനർത്ഥം. പരിശീലന പൈപ്പ്‌ലൈനുകൾ പ്രവർത്തിപ്പിക്കുന്നത് DVTech വെഞ്ചേഴ്‌സ് അല്ലെങ്കിൽ അതിൻ്റെ കരാർ ചെയ്ത AI ദാതാക്കളാണ് ഡാറ്റ പ്രോസസ്സിംഗ് കരാറുകൾക്ക് കീഴിൽ.';

