  @override
  String get legalDisclaimerAINotLawyerBody =>
      'പൊതു നിയമ കോർപ്പറയിൽ പരിശീലനം ലഭിച്ച വലിയ ഭാഷാ മോഡലുകളാണ് കുടയുടെ AI സംവിധാനങ്ങൾ. അവർ പ്രാക്ടീസ് സർട്ടിഫിക്കറ്റുകൾ കൈവശം വയ്ക്കുന്നില്ല, കോടതിയിൽ ഹാജരാകാൻ കഴിയില്ല, ഏതെങ്കിലും ബാർ അസോസിയേഷനോ ലോ സൊസൈറ്റിയോ നിയന്ത്രിക്കുന്നില്ല, കൂടാതെ ഒരു അഭിഭാഷകനെപ്പോലെ നിങ്ങളോട് പരിചരണത്തിൻ്റെ കടമയും അവർക്കില്ല. AI ഔട്ട്പുട്ടുകളിൽ വസ്തുതാപരമായ പിശകുകളോ ഭ്രമാത്മകതയോ അടങ്ങിയിരിക്കാം; നിങ്ങളുടെ നിർദ്ദിഷ്ട വസ്തുതകൾക്ക് പ്രസക്തമായ മെറ്റീരിയൽ പരിഗണനകൾ ഒഴിവാക്കുക; ഭേദഗതി ചെയ്തതോ റദ്ദാക്കിയതോ അസാധുവാക്കിയതോ ആയ നിയമങ്ങൾ അല്ലെങ്കിൽ കേസുകൾ ഉദ്ധരിക്കുക; സമീപകാല നിയമനിർമ്മാണ മാറ്റങ്ങൾ കണക്കിലെടുക്കുന്നതിൽ പരാജയപ്പെടുന്നു; സങ്കീർണ്ണമോ അവ്യക്തമോ ആയ നിയമപരമായ ചോദ്യങ്ങൾ തെറ്റായി വ്യാഖ്യാനിക്കുക. നിങ്ങൾ എല്ലാ AI ഔട്ട്‌പുട്ടും അന്വേഷണത്തിനുള്ള ഒരു ആരംഭ പോയിൻ്റായി കണക്കാക്കണം, അന്തിമ ഉത്തരമല്ല.';

  @override
  String get legalDisclaimerAINotLawyerHeading => '3. AI ഒരു അഭിഭാഷകനല്ല';

  @override
  String get legalDisclaimerCitationBody =>
      'കുട ഒരു ചട്ടം, നിയന്ത്രണം, നിയമം അല്ലെങ്കിൽ ജുഡീഷ്യൽ തീരുമാനം എന്നിവ ഉദ്ധരിക്കുമ്പോൾ, നിങ്ങൾ സ്വതന്ത്രമായി പരിശോധിക്കേണ്ടതുണ്ട്: (എ) ഉദ്ധരിച്ച ഉറവിടം നിലവിലുണ്ടെന്ന്; (ബി) അവലംബം കൃത്യമാണെന്ന് (വിഭാഗം, ഉപവിഭാഗം, വർഷം); (സി) സ്രോതസ്സ് നിലവിൽ പ്രാബല്യത്തിലുണ്ടെന്നും ഭേദഗതി വരുത്തുകയോ റദ്ദാക്കുകയോ ചെയ്തിട്ടില്ല; (d) ഉദ്ധരിച്ച വാചകം ഉറവിടത്തെ കൃത്യമായി പ്രതിഫലിപ്പിക്കുന്നു. AI ഉദ്ധരണി പിശകുകൾ - കെട്ടിച്ചമച്ച ഉദ്ധരണികൾ ഉൾപ്പെടെ - നിലവിലുള്ള എല്ലാ AI സിസ്റ്റങ്ങളുടെയും അറിയപ്പെടുന്ന പരിമിതിയാണ്. സ്വതന്ത്രമായ സ്ഥിരീകരണമില്ലാതെ നിയമനടപടികളിലോ ഉപദേശങ്ങളിലോ ഫയലിംഗുകളിലോ ഒരിക്കലും ഒരു ഉദ്ധരണിയെ ആശ്രയിക്കരുത്.';

  @override
  String get legalDisclaimerCitationHeading => '4. ഉദ്ധരണി കൃത്യത';

  @override
  String get legalDisclaimerJurisdictionBody =>
      'ഇന്ത്യ: AI വിശകലനം കേന്ദ്ര നിയമനിർമ്മാണം, വ്യക്തമാക്കിയിട്ടുള്ള സംസ്ഥാന നിയമങ്ങൾ, ജുഡീഷ്യൽ തീരുമാനങ്ങൾ എന്നിവയെ അടിസ്ഥാനമാക്കിയുള്ളതാണ്. ഇത് ജില്ലാ കോടതിതല പ്രാക്ടീസ്, പ്രാദേശിക ബാർ കസ്റ്റംസ്, അല്ലെങ്കിൽ ക്രോഡീകരിക്കാത്ത നടപടിക്രമ നിയമങ്ങൾ എന്നിവ കണക്കിലെടുക്കുന്നില്ല. യുണൈറ്റഡ് സ്റ്റേറ്റ്സ്: AI വിശകലനം ഫെഡറൽ നിയമത്തെയും തിരഞ്ഞെടുത്ത സംസ്ഥാന നിയമത്തെയും അടിസ്ഥാനമാക്കിയുള്ളതാണ്. യുഎസ് നിയമ വിശകലനം സംസ്ഥാന-നിർദ്ദിഷ്‌ട ലൈസൻസുള്ള കൗൺസലിനു പകരമല്ല. സ്ഥിരീകരിക്കപ്പെട്ട വക്കീൽ അവലോകനം കൂടാതെ ഇമിഗ്രേഷൻ, ക്രിമിനൽ പ്രതിരോധം അല്ലെങ്കിൽ നികുതി കാര്യങ്ങൾ എന്നിവയ്ക്ക് ലഭ്യമല്ല. കെനിയ: കെനിയൻ ചട്ടങ്ങൾ, അനുബന്ധ നിയമനിർമ്മാണം, പ്രസിദ്ധീകരിച്ച ഹൈക്കോടതി, അപ്പീൽ കോടതി തീരുമാനങ്ങൾ എന്നിവ വിശകലനം ചെയ്യുന്നു. ഇത് ആചാരപരമായ നിയമം, മജിസ്‌ട്രേറ്റ് കോടതി വ്യതിയാനങ്ങൾ, അല്ലെങ്കിൽ പ്രസിദ്ധീകരിക്കാത്ത വിധികൾ എന്നിവ കണക്കിലെടുക്കുന്നില്ല. യുണൈറ്റഡ് കിംഗ്ഡം: വിശകലനം ഇംഗ്ലീഷ്, വെൽഷ് നിയമങ്ങൾ ഉൾക്കൊള്ളുന്നു. സ്കോട്ട്സ് നിയമം, നോർത്തേൺ ഐറിഷ് നിയമം, വികസിപ്പിച്ച കാര്യങ്ങൾ എന്നിവ കാര്യമായി വ്യത്യാസപ്പെട്ടേക്കാം; അധികാരപരിധിയിലുള്ള പ്രത്യേക ഉപദേശം തേടുക.';

