  @override
  String get legalDisclaimerNoPrivilegeBody =>
      'Umbrella\'s AI-യുമായുള്ള ആശയവിനിമയങ്ങൾ ഏതെങ്കിലും അധികാരപരിധിയിലെ അറ്റോർണി-ക്ലയൻ്റ് പ്രത്യേകാവകാശമോ നിയമപരമായ പ്രൊഫഷണൽ പ്രത്യേകാവകാശമോ മുഖേന പരിരക്ഷിക്കപ്പെട്ടിട്ടില്ല. നിങ്ങൾ പ്രത്യേകാവകാശത്തിന് കീഴിൽ പരിരക്ഷിക്കാൻ ഉദ്ദേശിക്കുന്ന പ്ലാറ്റ്‌ഫോമിലേക്ക് വിവരങ്ങൾ സമർപ്പിക്കരുത്. അംബ്രല്ല മാർക്കറ്റ്‌പ്ലെയ്‌സ് വഴി നിങ്ങൾ ഒരു ലൈസൻസുള്ള അഭിഭാഷകനുമായി ഇടപഴകുകയാണെങ്കിൽ, എക്‌സിക്യൂട്ട് ചെയ്‌ത റീട്ടെയ്‌നർ കരാറിന് കീഴിൽ ആ അഭിഭാഷകനുമായുള്ള നിങ്ങളുടെ ആശയവിനിമയത്തിന് പ്രത്യേകാവകാശം അറ്റാച്ചുചെയ്യാം, എന്നാൽ നിങ്ങളുടെ മുൻകാല AI ഇടപെടലുകളോട് അല്ല.';

