  @override
  String get legalDisclaimerPageDescription =>
      'കുടയുടെ AI- സൃഷ്ടിച്ച നിയമപരമായ വിവരങ്ങൾ, അതിൻ്റെ പരിമിതികൾ, ഉപയോക്തൃ ഉത്തരവാദിത്തങ്ങൾ എന്നിവയെക്കുറിച്ചുള്ള പ്രധാന അറിയിപ്പുകൾ. അംബ്രല്ല പ്ലാറ്റ്‌ഫോമിലൂടെ ഡിവിടെക് വെഞ്ച്വേഴ്‌സ് വാഗ്ദാനം ചെയ്യുന്ന എല്ലാ ഉൽപ്പന്നങ്ങൾക്കും ഫീച്ചറുകൾക്കും ഈ നിരാകരണം ബാധകമാണ്.';

  @override
  String get legalDisclaimerPageTitle => 'നിയമപരമായ നിരാകരണം';

  @override
  String get legalDisclaimerRegulatoryBody =>
      'ഡിവിടെക് വെഞ്ചേഴ്‌സ് ഒരു സാങ്കേതിക കമ്പനിയാണ്, നിയന്ത്രിത നിയമ സേവന ദാതാവല്ല. സോളിസിറ്റേഴ്‌സ് റെഗുലേഷൻ അതോറിറ്റി (യുകെ), ബാർ കൗൺസിൽ ഓഫ് ഇന്ത്യ, ലോ സൊസൈറ്റി ഓഫ് കെനിയ, ഏതെങ്കിലും യുഎസ് സ്റ്റേറ്റ് ബാർ അല്ലെങ്കിൽ മറ്റേതെങ്കിലും നിയമ റെഗുലേറ്ററി ബോഡി എന്നിവ നിയമ സേവനങ്ങൾ നൽകുന്നതിന് ഞങ്ങൾക്ക് അംഗീകാരം നൽകിയിട്ടില്ല. നിയമ സേവന നിയമം 2007 (യുകെ) അല്ലെങ്കിൽ മറ്റ് അധികാരപരിധിയിലെ തത്തുല്യമായ നിയമനിർമ്മാണത്തിൽ നിർവ്വചിച്ചിരിക്കുന്ന നിയന്ത്രിത നിയമപരമായ പ്രവർത്തനങ്ങൾ കുട പ്ലാറ്റ്ഫോം നൽകുന്നില്ല.';

