  @override
  String get legalPrivacyAutomatedBody =>
      'നിയമപരമായ വിശകലനം സൃഷ്ടിക്കുന്നതിനും പ്രശ്നങ്ങൾ തിരിച്ചറിയുന്നതിനും പ്രവർത്തനങ്ങൾ നിർദ്ദേശിക്കുന്നതിനും കുട AI ഉപയോഗിക്കുന്നു. ഈ AI ഔട്ട്‌പുട്ടുകൾ വിവരദായകമാണ്, മാത്രമല്ല നിങ്ങളുടെ നിയമപരമായ അവകാശങ്ങളെക്കുറിച്ചുള്ള തീരുമാനങ്ങൾ ഉൾക്കൊള്ളുന്നില്ല. മാനുഷിക അവലോകനം കൂടാതെ നിയമപരമോ സമാനമായ കാര്യമായ ഫലമോ ഉള്ള പൂർണ്ണമായ യാന്ത്രിക തീരുമാനങ്ങളൊന്നും നിങ്ങളെക്കുറിച്ച് എടുക്കില്ല. വഞ്ചന കണ്ടെത്തുന്നതിനുള്ള ഞങ്ങളുടെ AI റിസ്ക്-സ്കോറിംഗ് പ്ലാറ്റ്ഫോം ആക്‌സസിനെ ബാധിച്ചേക്കാം; അത്തരമൊരു തീരുമാനത്തെക്കുറിച്ച് നിങ്ങൾക്ക് മനുഷ്യ അവലോകനം അഭ്യർത്ഥിക്കാം.';

  @override
  String get legalPrivacyAutomatedHeading => '11. സ്വയമേവയുള്ള തീരുമാനമെടുക്കൽ';

  @override
  String get legalPrivacyChangesBody =>
      'ഞങ്ങൾ ഈ സ്വകാര്യതാ നയം കാലാകാലങ്ങളിൽ അപ്ഡേറ്റ് ചെയ്തേക്കാം. മെറ്റീരിയൽ മാറ്റങ്ങൾ പ്രാബല്യത്തിൽ വരുന്നതിന് കുറഞ്ഞത് 30 ദിവസം മുമ്പെങ്കിലും ഇമെയിൽ വഴിയും ആപ്പ് അറിയിപ്പ് വഴിയും അറിയിക്കും. പ്രാബല്യത്തിൽ വരുന്ന തീയതിക്ക് ശേഷവും പ്ലാറ്റ്‌ഫോമിൻ്റെ തുടർച്ചയായ ഉപയോഗം അപ്‌ഡേറ്റ് ചെയ്ത നയത്തിൻ്റെ സ്വീകാര്യതയെ അർത്ഥമാക്കുന്നു.';

  @override
  String get legalPrivacyChangesHeading => '13. ഈ നയത്തിലെ മാറ്റങ്ങൾ';

  @override
  String get legalPrivacyChildrenBody =>
      '18 വയസ്സിന് താഴെയുള്ളവരെ കുട വയ്ക്കില്ല. കുട്ടികളിൽ നിന്ന് ഞങ്ങൾ അറിഞ്ഞുകൊണ്ട് വ്യക്തിഗത വിവരങ്ങൾ ശേഖരിക്കുന്നില്ല. ഒരു കുട്ടി ഞങ്ങൾക്ക് ഡാറ്റ സമർപ്പിച്ചതായി നിങ്ങൾ വിശ്വസിക്കുന്നുവെങ്കിൽ, support@odaflow.com-മായി ബന്ധപ്പെടുക, ഞങ്ങൾ അത് ഉടനടി ഇല്ലാതാക്കും.';

