  @override
  String get legalPrivacyCookiesBody =>
      'കർശനമായി ആവശ്യമായ കുക്കികൾ (സെഷൻ മാനേജ്മെൻ്റ്, സുരക്ഷാ ടോക്കണുകൾ) എപ്പോഴും സജീവമാണ്. ഫങ്ഷണൽ കുക്കികൾ (ഭാഷാ മുൻഗണന, തീം) ആദ്യ ഉപയോഗത്തിൽ സജ്ജീകരിച്ചിരിക്കുന്നു, ബ്രൗസർ ക്രമീകരണങ്ങളിൽ മായ്‌ക്കാനാകും. Analytics കുക്കികൾ (Vercel, Sentry) കുക്കി ബാനർ വഴി നിങ്ങളുടെ സമ്മതത്തോടെ മാത്രമേ സജ്ജീകരിച്ചിട്ടുള്ളൂ. ഞങ്ങൾ പരസ്യമോ ​​ക്രോസ്-സൈറ്റ് ട്രാക്കിംഗ് കുക്കികളോ ഉപയോഗിക്കുന്നില്ല.';

