  @override
  String get legalPrivacyLegalBasisBody =>
      'നിങ്ങളുടെ അധികാരപരിധിയെ ആശ്രയിച്ച് ഇനിപ്പറയുന്ന നിയമപരമായ അടിസ്ഥാനങ്ങൾക്ക് കീഴിൽ ഞങ്ങൾ വ്യക്തിഗത ഡാറ്റ പ്രോസസ്സ് ചെയ്യുന്നു: (എ) കരാർ - നിങ്ങൾ സൈൻ അപ്പ് ചെയ്‌തിരിക്കുന്ന സേവനങ്ങൾ നൽകുന്നതിന് ആവശ്യമായ പ്രോസസ്സിംഗ്; (ബി) നിയമാനുസൃത താൽപ്പര്യങ്ങൾ - വഞ്ചന തടയൽ, പ്ലാറ്റ്ഫോം സുരക്ഷ, ഉൽപ്പന്ന മെച്ചപ്പെടുത്തൽ; (സി) സമ്മതം - AI പരിശീലനം, മാർക്കറ്റിംഗ് ഇമെയിലുകൾ, കുക്കികൾ എന്നിവ കർശനമായി ആവശ്യമാണ്; (d) നിയമപരമായ ബാധ്യത - ബാധകമായ നിയമം പാലിക്കൽ. ഇന്ത്യയെ സംബന്ധിച്ചിടത്തോളം, പ്രോസസ്സിംഗ് നിയന്ത്രിക്കുന്നത് ഡിജിറ്റൽ പേഴ്സണൽ ഡാറ്റ പ്രൊട്ടക്ഷൻ ആക്ട് 2023 (DPDP ആക്ട്) ആണ്. യുകെ/ഇയുവിന്, പ്രോസസ്സിംഗ് യുകെ ജിഡിപിആർ, ഇയു ജിഡിപിആർ എന്നിവയ്ക്ക് അനുസൃതമാണ്. കെനിയയെ സംബന്ധിച്ചിടത്തോളം, പ്രോസസ്സിംഗ് ഡാറ്റ പ്രൊട്ടക്ഷൻ ആക്റ്റ് 2019-ന് അനുസൃതമാണ്. യുഎസ് ഉപയോക്താക്കൾക്ക്, CCPA/CPRA ഉൾപ്പെടെയുള്ള ബാധകമായ സംസ്ഥാന സ്വകാര്യതാ നിയമങ്ങൾ ഞങ്ങൾ പാലിക്കുന്നു.';

