  @override
  String get legalStandardDisclaimer =>
      'കുട നിയമപരമായ വിവരങ്ങൾ, ഡോക്യുമെൻ്റ് വിശദീകരണങ്ങൾ, ഇഷ്യൂ ഐഡൻ്റിഫിക്കേഷൻ, റിസ്ക് വിശകലനം എന്നിവ നൽകുന്നു. ഇത് ഒരു നിയമ സ്ഥാപനമല്ല, ലൈസൻസുള്ള അഭിഭാഷകനെ മാറ്റിസ്ഥാപിക്കുന്നില്ല. നിങ്ങളുടെ സാഹചര്യവുമായി ബന്ധപ്പെട്ട നിയമോപദേശത്തിന്, നിങ്ങളുടെ അധികാരപരിധിയിലുള്ള ഒരു യോഗ്യതയുള്ള അഭിഭാഷകനെ സമീപിക്കുക.';

  @override
  String get legalTermsAIOutputsBody =>
      'AI ഔട്ട്‌പുട്ടുകൾ സൃഷ്ടിക്കുന്നത് വലിയ ഭാഷാ മോഡലുകളാണ്, അവ വിവര ആവശ്യങ്ങൾക്കായി മാത്രം നൽകിയിരിക്കുന്നു. അവർ നിയമോപദേശം നൽകുന്നില്ല, ഒരു അറ്റോർണി-ക്ലയൻ്റ് ബന്ധം സൃഷ്ടിക്കരുത്, കൂടാതെ യോഗ്യതയുള്ള ഒരു അഭിഭാഷകനിൽ നിന്നുള്ള ഉപദേശത്തിന് പകരമായി ആശ്രയിക്കരുത്. AI ഔട്ട്പുട്ടുകൾ അപൂർണ്ണമോ കൃത്യമല്ലാത്തതോ കാലഹരണപ്പെട്ടതോ ആകാം. ചട്ടങ്ങളിലേക്കും കേസുകളിലേക്കും ഉള്ള ഉദ്ധരണികൾ സ്വതന്ത്രമായി പരിശോധിച്ചുറപ്പിച്ചിരിക്കണം. AI ഔട്ട്‌പുട്ടുകളെ അടിസ്ഥാനമാക്കി എടുക്കുന്ന ഏതൊരു പ്രവർത്തനത്തിനും നിങ്ങൾ മാത്രമാണ് ഉത്തരവാദി.';

  @override
  String get legalTermsAIOutputsHeading => '9. AI ഔട്ട്പുട്ടുകളുടെ സ്വഭാവം';

  @override
  String get legalTermsAccountBody =>
      'നിങ്ങൾ കൃത്യവും പൂർണ്ണവുമായ രജിസ്ട്രേഷൻ വിവരങ്ങൾ നൽകുകയും അത് അപ്ഡേറ്റ് ചെയ്യുകയും വേണം. നിങ്ങളുടെ ക്രെഡൻഷ്യലുകളുടെ രഹസ്യസ്വഭാവം നിലനിർത്തുന്നതിനും നിങ്ങളുടെ അക്കൗണ്ടിന് കീഴിലുള്ള എല്ലാ പ്രവർത്തനങ്ങൾക്കും നിങ്ങൾ ഉത്തരവാദിയാണ്. support@odaflow.com എന്നതിൽ ഏതെങ്കിലും അനധികൃത ആക്‌സസ്സ് നിങ്ങൾ ഞങ്ങളെ ഉടൻ അറിയിക്കണം. ഈ നിബന്ധനകൾ ലംഘിക്കുന്ന അക്കൗണ്ടുകൾ പ്രവർത്തനരഹിതമാക്കാനുള്ള അവകാശം ഞങ്ങളിൽ നിക്ഷിപ്തമാണ്.';

  @override
  String get legalTermsAccountHeading => '3. അക്കൗണ്ട് രജിസ്ട്രേഷൻ';

  @override
  String get legalTermsAgreementBody =>
      'ഒരു അക്കൗണ്ട് സൃഷ്‌ടിക്കുന്നതിലൂടെയോ ഏതെങ്കിലും അംബ്രല്ല സേവനം ഉപയോഗിക്കുന്നതിലൂടെയോ, ഈ നിബന്ധനകൾക്ക് വിധേയമാകുമെന്ന് നിങ്ങൾ സമ്മതിക്കുന്നു. ഒരു നിയമ സ്ഥാപനത്തിൻ്റെയോ കമ്പനിയുടെയോ മറ്റ് നിയമപരമായ സ്ഥാപനത്തിൻ്റെയോ പേരിലാണ് നിങ്ങൾ പ്ലാറ്റ്ഫോം ഉപയോഗിക്കുന്നതെങ്കിൽ, ആ സ്ഥാപനത്തെ ബന്ധിപ്പിക്കാൻ നിങ്ങൾക്ക് അധികാരമുണ്ടെന്ന് നിങ്ങൾ പ്രതിനിധീകരിക്കുന്നു. നിങ്ങൾ ഈ നിബന്ധനകൾ അംഗീകരിക്കുന്നില്ലെങ്കിൽ, നിങ്ങൾ പ്ലാറ്റ്ഫോം ഉപയോഗിക്കരുത്. ഉപയോക്താക്കൾക്ക് കുറഞ്ഞത് 18 വയസ്സ് പ്രായമുണ്ടായിരിക്കണം.';

  @override
  String get legalTermsAgreementHeading => '1. സ്വീകാര്യത';

  @override
  String get legalTermsChangesBody =>
      'ഞങ്ങൾ ഈ നിബന്ധനകൾ കാലാകാലങ്ങളിൽ അപ്ഡേറ്റ് ചെയ്തേക്കാം. മെറ്റീരിയൽ മാറ്റങ്ങൾ പ്രാബല്യത്തിൽ വരുന്നതിന് കുറഞ്ഞത് 30 ദിവസം മുമ്പെങ്കിലും ഇമെയിൽ വഴിയും ആപ്പ് അറിയിപ്പ് വഴിയും അറിയിക്കും. പ്രാബല്യത്തിൽ വരുന്ന തീയതിക്ക് ശേഷം തുടർച്ചയായി ഉപയോഗിക്കുന്നത് സ്വീകാര്യതയാണ്.';

  @override
  String get legalTermsChangesHeading => '20. ഈ നിബന്ധനകളിലെ മാറ്റങ്ങൾ';

  @override
  String get legalTermsConfidentialityBody =>
      'നിങ്ങളുടെ ഉള്ളടക്കവും കാര്യ ഡാറ്റയും ഞങ്ങൾ രഹസ്യാത്മകമായി കണക്കാക്കുന്നു, ഞങ്ങളുടെ സ്വകാര്യതാ നയത്തിൽ വിവരിച്ചിരിക്കുന്നതോ നിയമപ്രകാരം ആവശ്യപ്പെടുന്നതോ അല്ലാതെ മൂന്നാം കക്ഷികൾക്ക് അത് വെളിപ്പെടുത്തില്ല. അഭിഭാഷക ഉപയോക്താക്കൾ ക്ലയൻ്റ്-രഹസ്യ ആശയവിനിമയങ്ങൾ ബാധകമായ പ്രൊഫഷണൽ പ്രിവിലേജ് നിയമങ്ങൾ പാലിക്കുന്നുണ്ടെന്ന് ഉറപ്പാക്കണം. ഞങ്ങളുടെ സിസ്റ്റങ്ങൾ വാടകക്കാരൻ്റെ ഡാറ്റയെ വേർതിരിക്കുന്നതിനാണ് നിർമ്മിച്ചിരിക്കുന്നത്.';

  @override
  String get legalTermsConfidentialityHeading => '13. രഹസ്യസ്വഭാവം';

  @override
  String get legalTermsContactBody =>
      'ഈ നിബന്ധനകളെക്കുറിച്ചുള്ള ചോദ്യങ്ങൾ: support@odaflow.com. ഡിവിടെക് വെഞ്ചേഴ്സ്, രജിസ്റ്റർ ചെയ്ത ഓഫീസ് വിശദാംശങ്ങൾ അഭ്യർത്ഥന പ്രകാരം ലഭ്യമാണ്.';

  @override
  String get legalTermsContactHeading => '21. ബന്ധപ്പെടുക';

  @override
  String get legalTermsDataBody =>
      'ഞങ്ങളുടെ സ്വകാര്യ ഡാറ്റയുടെ ശേഖരണവും ഉപയോഗവും സ്വകാര്യതാ നയത്തിൽ വിവരിച്ചിരിക്കുന്നു. AI പരിശീലനത്തിനും അനലിറ്റിക്‌സ് ഉപയോഗങ്ങൾക്കും ഡാറ്റ & AI സമ്മത നയത്തിൽ വിവരിച്ചിരിക്കുന്നതുപോലെ വ്യക്തമായ ഓപ്റ്റ്-ഇൻ ആവശ്യമാണ്.';

  @override
  String get legalTermsDataConsentLink => 'ഡാറ്റ & AI സമ്മത നയം';

  @override
  String get legalTermsDataHeading => '15. ഡാറ്റയും സ്വകാര്യതയും';

  @override
  String get legalTermsDataPrivacyLink => 'സ്വകാര്യതാ നയം';

  @override
  String get legalTermsDefinitionsBody =>
      '\"പ്ലാറ്റ്ഫോം\" എന്നാൽ umbrella.okaylegal.ai എന്നതും ബന്ധപ്പെട്ട എല്ലാ ആപ്ലിക്കേഷനുകളും API-കളും സേവനങ്ങളും എന്നാണ് അർത്ഥമാക്കുന്നത്. \"ഉപഭോക്തൃ ഉപയോക്താവ്\" എന്നാൽ സ്വന്തം നിയമപരമായ സാഹചര്യം മനസ്സിലാക്കാൻ പ്ലാറ്റ്ഫോം ഉപയോഗിക്കുന്ന ഒരു സ്വാഭാവിക വ്യക്തി എന്നാണ് അർത്ഥമാക്കുന്നത്. \"വക്കീൽ ഉപയോക്താവ്\" എന്നാൽ ലോയർ ഒഎസ് ഫീച്ചറുകൾ ഉപയോഗിക്കുന്ന ലൈസൻസുള്ള നിയമ വിദഗ്ധൻ എന്നാണ് അർത്ഥമാക്കുന്നത്. \"കുടിയാൻ\" എന്നാൽ ഒരു നിയമ സ്ഥാപനം അല്ലെങ്കിൽ ഉറച്ച സബ്‌സ്‌ക്രിപ്‌ഷനുള്ള സ്ഥാപനം എന്നാണ് അർത്ഥമാക്കുന്നത്. \"AI ഔട്ട്‌പുട്ട്\" എന്നാൽ അംബ്രല്ലയുടെ AI സിസ്റ്റങ്ങൾ സൃഷ്ടിച്ച ഏതെങ്കിലും വാചകം, വിശകലനം, ഡ്രാഫ്റ്റ് അല്ലെങ്കിൽ ശുപാർശ എന്നിവയാണ് അർത്ഥമാക്കുന്നത്. \"കാര്യം\" എന്നാൽ നിയമപരമായ കേസ് അല്ലെങ്കിൽ ലോയർ OS വഴി കൈകാര്യം ചെയ്യുന്ന ഇടപാട് എന്നാണ് അർത്ഥമാക്കുന്നത്. \"DVTech വെഞ്ചേഴ്‌സ്\" അല്ലെങ്കിൽ \"ഞങ്ങൾ\" എന്നാൽ പ്ലാറ്റ്‌ഫോമിൻ്റെ ഓപ്പറേറ്റർ എന്നാണ് അർത്ഥമാക്കുന്നത്.';

  @override
  String get legalTermsDefinitionsHeading => '2. നിർവചനങ്ങൾ';

  @override
  String get legalTermsDescription =>
      'ഈ നിബന്ധനകൾ നിങ്ങളുടെ കുടയുടെ ഉപയോഗത്തെ നിയന്ത്രിക്കുന്നു — ഡിവിടെക് വെഞ്ച്വേഴ്സ് നടത്തുന്ന AI- നേറ്റീവ് നിയമ പ്ലാറ്റ്ഫോം. പ്ലാറ്റ്‌ഫോമിൻ്റെ ഏതെങ്കിലും ഭാഗം ഉപയോഗിക്കുന്നതിന് മുമ്പ് ദയവായി അവ ശ്രദ്ധാപൂർവ്വം വായിക്കുക.';

  @override
  String get legalTermsDisputeBody =>
      'ഇന്ത്യയിലെ ഉപയോക്താക്കൾ: ഈ നിബന്ധനകൾ നിയന്ത്രിക്കുന്നത് ഇന്ത്യയുടെ നിയമങ്ങളാൽ; തർക്കങ്ങൾ ബംഗളൂരുവിൽ പ്രവർത്തിക്കുന്ന ആർബിട്രേഷൻ ആൻഡ് കൺസിലിയേഷൻ ആക്ട് 1996 പ്രകാരം ബൈൻഡിംഗ് ആർബിട്രേഷൻ വഴി പരിഹരിക്കപ്പെടും. യുണൈറ്റഡ് സ്‌റ്റേറ്റ്‌സ് ഉപയോക്താക്കൾ: ഡെലവെയറിൽ ഇരിക്കുന്ന AAA വാണിജ്യ ആർബിട്രേഷൻ നിയമങ്ങൾ പ്രകാരം ബൈൻഡിംഗ് ആർബിട്രേഷൻ വഴി തർക്കങ്ങൾ പരിഹരിക്കപ്പെടും; ക്ലാസ് നടപടി ഒഴിവാക്കൽ ബാധകമാണ്. കെനിയ ഉപയോക്താക്കൾ: ഈ നിബന്ധനകൾ കെനിയയുടെ നിയമങ്ങളാൽ നിയന്ത്രിക്കപ്പെടുന്നു; നെയ്‌റോബി സെൻ്റർ ഫോർ ഇൻ്റർനാഷണൽ ആർബിട്രേഷൻ (എൻസിഐഎ) നിയമങ്ങൾക്ക് കീഴിലാണ് തർക്കങ്ങൾ പരിഹരിക്കേണ്ടത്. യുണൈറ്റഡ് കിംഗ്ഡം ഉപയോക്താക്കൾ: ഈ നിബന്ധനകൾ ഇംഗ്ലീഷ് നിയമത്താൽ നിയന്ത്രിക്കപ്പെടുന്നു; തർക്കങ്ങൾ ഇംഗ്ലണ്ടിലെയും വെയിൽസിലെയും കോടതികളുടെ പ്രത്യേക അധികാരപരിധിയിൽ സമർപ്പിക്കും. എല്ലാ സാഹചര്യങ്ങളിലും, യോഗ്യതയുള്ള ഒരു കോടതിയിൽ നിന്ന് അടിയന്തിര ഇൻജങ്ക്റ്റീവ് റിലീഫ് തേടുന്നതിൽ നിന്ന് നിങ്ങളെ ഒന്നും തടയുന്നില്ല.';

  @override
  String get legalTermsDisputeHeading => '18. തർക്ക പരിഹാരവും ഭരണനിയമവും';

  @override
  String get legalTermsIPContentBody =>
      'നിങ്ങൾ പ്ലാറ്റ്‌ഫോമിലേക്ക് സമർപ്പിക്കുന്ന എല്ലാ ഉള്ളടക്കത്തിൻ്റെയും ഉടമസ്ഥാവകാശം നിങ്ങൾ നിലനിർത്തുന്നു. ഉള്ളടക്കം സമർപ്പിക്കുന്നതിലൂടെ, സേവനങ്ങൾ ഡെലിവർ ചെയ്യുന്നതിനായി മാത്രം നിങ്ങളുടെ ഉള്ളടക്കം പ്രോസസ്സ് ചെയ്യാനും സംഭരിക്കാനും പ്രദർശിപ്പിക്കാനും നിങ്ങൾ DVTech വെഞ്ച്വറുകൾക്ക് ലോകമെമ്പാടുമുള്ള, റോയൽറ്റി രഹിത, നോൺ-എക്‌സ്‌ക്ലൂസീവ് ലൈസൻസ് നൽകുന്നു. ഡാറ്റ & AI സമ്മത നയത്തിന് കീഴിൽ നിങ്ങൾ തിരഞ്ഞെടുക്കുന്നില്ലെങ്കിൽ ഈ ലൈസൻസ് AI പരിശീലനത്തിലേക്ക് വ്യാപിക്കുന്നില്ല.';

  @override
  String get legalTermsIPHeading => '12. ബൗദ്ധിക സ്വത്ത്';

  @override
  String get legalTermsIPPlatformBody =>
      'അംബ്രല്ല പ്ലാറ്റ്‌ഫോം, ബ്രാൻഡ്, അന്തർലീനമായ AI മോഡലുകൾ, സാങ്കേതികവിദ്യ എന്നിവയിലെ എല്ലാ അവകാശങ്ങളും DVTech വെഞ്ചേഴ്‌സിന് സ്വന്തമാണ്. നിങ്ങളുടെ സബ്‌സ്‌ക്രിപ്‌ഷൻ്റെ കാലയളവിലേക്ക് പ്ലാറ്റ്‌ഫോം ഉപയോഗിക്കുന്നതിന് നിങ്ങൾക്ക് പരിമിതമായ, എക്‌സ്‌ക്ലൂസീവ് അല്ലാത്ത, കൈമാറ്റം ചെയ്യാനാവാത്ത ലൈസൻസ് അനുവദിച്ചിരിക്കുന്നു.';

  @override
  String get legalTermsIndemnityBody =>
      'നിരുപദ്രവകാരികളായ DVTech വെഞ്ച്വറുകൾ, അതിൻ്റെ ഓഫീസർമാർ, ഡയറക്ടർമാർ, ജീവനക്കാർ, ഏജൻ്റുമാർ എന്നിവരിൽ നിന്ന് ഉണ്ടാകുന്ന ഏതെങ്കിലും ക്ലെയിമുകൾ, നാശനഷ്ടങ്ങൾ, നഷ്ടങ്ങൾ, ചെലവുകൾ (ന്യായമായ നിയമപരമായ ഫീസ് ഉൾപ്പെടെ) എന്നിവയിൽ നിന്ന് നഷ്ടപരിഹാരം നൽകാനും പ്രതിരോധിക്കാനും കൈവശം വയ്ക്കാനും നിങ്ങൾ സമ്മതിക്കുന്നു: (എ) ഈ നിബന്ധനകൾ ലംഘിച്ചുകൊണ്ട് നിങ്ങളുടെ പ്ലാറ്റ്ഫോം ഉപയോഗിക്കുന്നത്; (ബി) ബാധകമായ ഏതെങ്കിലും നിയമത്തിൻ്റെ നിങ്ങളുടെ ലംഘനം; (സി) നിങ്ങൾ സമർപ്പിക്കുന്ന ഉള്ളടക്കം ഒരു മൂന്നാം കക്ഷിയുടെ അവകാശങ്ങൾ ലംഘിക്കുന്നു; (d) പ്ലാറ്റ്‌ഫോം ഉപയോഗിച്ച് നിങ്ങളുടെ ക്ലയൻ്റുകൾക്ക് നിങ്ങൾ നൽകുന്ന നിയമോപദേശമോ സേവനങ്ങളോ.';

  @override
  String get legalTermsIndemnityHeading => '17. നഷ്ടപരിഹാരം';

  @override
  String get legalTermsLawyerUsersBody =>
      'അഭിഭാഷക ഉപയോക്താക്കൾ സ്വതന്ത്ര ലൈസൻസുള്ള പ്രൊഫഷണലുകളാണ്. വക്കീൽ OS ഉപയോഗിക്കുന്നതിലൂടെ, നിങ്ങളുടെ അധികാരപരിധിയിൽ സാധുവായ ഒരു പ്രാക്ടീസ് സർട്ടിഫിക്കറ്റ് കൈവശമുണ്ടെന്നും ബാധകമായ പ്രൊഫഷണൽ പെരുമാറ്റ നിയമങ്ങൾക്കും ബാർ നിയന്ത്രണങ്ങൾക്കും അനുസൃതമായി നിങ്ങൾ പ്ലാറ്റ്ഫോം ഉപയോഗിക്കുമെന്നും നിങ്ങൾ സ്ഥിരീകരിക്കുന്നു. നിങ്ങളുടെ ക്ലയൻ്റുകൾക്ക് നിങ്ങൾ നൽകുന്ന എല്ലാ നിയമപരമായ ജോലികളുടെയും ഉപദേശത്തിൻ്റെയും ഗുണനിലവാരത്തിനും നിയമസാധുതയ്ക്കും നിങ്ങൾ മാത്രമാണ് ഉത്തരവാദി. കുട ഉപകരണങ്ങൾ നൽകുന്നു - ഇത് അഭിഭാഷക ഉപയോക്താക്കളുടെ പ്രൊഫഷണൽ പെരുമാറ്റത്തിന് മേൽനോട്ടം വഹിക്കുകയോ ഉറപ്പ് നൽകുകയോ ചെയ്യുന്നില്ല.';

  @override
  String get legalTermsLawyerUsersHeading => '11. അഭിഭാഷക ഉപയോക്താക്കൾ';

  @override
  String get legalTermsLiabilityBody =>
      'ബാധകമായ നിയമം അനുവദനീയമായ പരമാവധി പരിധി വരെ: (എ) ഈ നിബന്ധനകളിൽ നിന്നോ അതുമായി ബന്ധപ്പെട്ടോ ഉണ്ടാകുന്ന ഏതൊരു ക്ലെയിമിനും DVTECH വെഞ്ചേഴ്സിൻ്റെ മൊത്തത്തിലുള്ള ബാധ്യത അല്ലെങ്കിൽ അതിനുള്ള പ്ലാറ്റ്ഫോം അതിൻ്റെ പരിധിയാണ് ക്ലെയിമിന് മുമ്പുള്ള 12 മാസം; (ബി) പരോക്ഷമോ, ആകസ്മികമോ, പ്രത്യേകമോ, അനന്തരമോ, ശിക്ഷാപരമായതോ ആയ നാശനഷ്ടങ്ങൾ, ലാഭനഷ്ടം, ഡാറ്റ നഷ്ടം, അല്ലെങ്കിൽ ഗുഡ്‌വിൽ നഷ്ടം എന്നിവയ്ക്ക് ഞങ്ങൾ ബാധ്യസ്ഥരല്ല. അത്തരം നാശനഷ്ടങ്ങൾ ഉണ്ടാകാനുള്ള സാധ്യതയെക്കുറിച്ച് ഞങ്ങൾ ഉപദേശിച്ചിട്ടുണ്ടെങ്കിലും ഈ പരിമിതികൾ ബാധകമാണ്.';

  @override
  String get legalTermsLiabilityHeading => '16. ബാധ്യതയുടെ പരിമിതി';

  @override
  String get legalTermsNotLawFirmBody =>
      'കുട ഒരു സാങ്കേതിക പ്ലാറ്റ്ഫോമാണ്, ഒരു നിയമ സ്ഥാപനമല്ല. DVTech വെഞ്ചേഴ്സ് നിയമോപദേശമോ നിയമപരമായ പ്രാതിനിധ്യമോ നൽകുന്നില്ല. പ്ലാറ്റ്‌ഫോമിൻ്റെ ഉപയോഗം നിങ്ങളും DVTech വെഞ്ചേഴ്‌സും തമ്മിൽ ഒരു അറ്റോർണി-ക്ലയൻ്റ് ബന്ധം സൃഷ്ടിക്കുന്നില്ല. സ്വതന്ത്ര ലൈസൻസുള്ള അഭിഭാഷകരുമായി അഭിഭാഷക മാർക്കറ്റ് നിങ്ങളെ ബന്ധിപ്പിക്കുന്നു; ഒരു മാർക്കറ്റ്‌പ്ലെയ്‌സ് വക്കീലുമായുള്ള ഏതൊരു ഇടപഴകലും നിങ്ങളും ആ അഭിഭാഷകനും തമ്മിലുള്ള ഒരു പ്രത്യേക റിട്ടൈനർ കരാറാണ് നിയന്ത്രിക്കുന്നത്.';

