  @override
  String get legalTermsPermittedUseBody =>
      'നിങ്ങൾക്ക് ഈ പ്ലാറ്റ്‌ഫോം ഉപയോഗിക്കാം: വ്യക്തിപരമോ തൊഴിൽപരമോ ആയ ഉപയോഗത്തിനായി AI സൃഷ്ടിച്ച നിയമപരമായ വിവരങ്ങൾ നേടുക; നിയമപരമായ കാര്യങ്ങൾ, ക്ലയൻ്റുകൾ, ബില്ലിംഗ്, ഡോക്യുമെൻ്റുകൾ എന്നിവ കൈകാര്യം ചെയ്യുക (വക്കീൽ OS); ലൈസൻസുള്ള അഭിഭാഷകരുമായി ബന്ധപ്പെടാൻ വക്കീൽ മാർക്കറ്റിൽ പ്രവേശിക്കുക; കൂടാതെ ഞങ്ങളുടെ ഡോക്യുമെൻ്റഡ് API വഴി പ്ലാറ്റ്ഫോം നിങ്ങളുടെ സിസ്റ്റങ്ങളുമായി സംയോജിപ്പിക്കുക.';

  @override
