  @override
  String get legalTermsProhibitedUseBody =>
      'നിങ്ങൾ പാടില്ല: (എ) ഒരു അഭിഭാഷകനെയോ ജഡ്ജിയെയോ സർക്കാർ ഉദ്യോഗസ്ഥനെയോ ആൾമാറാട്ടം നടത്തുക; (ബി) വക്കീൽ അവലോകനം കൂടാതെ മൂന്നാം കക്ഷികൾക്ക് ഔപചാരിക നിയമോപദേശമായി AI ഔട്ട്പുട്ടുകൾ ഉപയോഗിക്കുക; (സി) നിയമവിരുദ്ധമോ അപകീർത്തികരമോ വഞ്ചനാപരമോ ആയ ഉള്ളടക്കം സമർപ്പിക്കുക; (ഡി) അടിസ്ഥാന AI മോഡലുകളോ പരിശീലന ഡാറ്റയോ റിവേഴ്സ്-എൻജിനീയർ, സ്ക്രാപ്പ് അല്ലെങ്കിൽ എക്സ്ട്രാക്റ്റ് ചെയ്യാൻ ശ്രമിക്കുക; (ഇ) രേഖാമൂലമുള്ള സമ്മതമില്ലാതെ പ്ലാറ്റ്‌ഫോമിലേക്കുള്ള പുനർവിൽപ്പന അല്ലെങ്കിൽ സബ്‌ലൈസൻസ് ആക്‌സസ്; (എഫ്) ഡാറ്റ സംരക്ഷണം, ഉപഭോക്തൃ സംരക്ഷണം, നിയമപരമായ തൊഴിൽ നിയമങ്ങൾ എന്നിവ ഉൾപ്പെടെ, ബാധകമായ നിയമം ലംഘിക്കുന്ന ഏതെങ്കിലും വിധത്തിൽ പ്ലാറ്റ്ഫോം ഉപയോഗിക്കുക; (ജി) മൂന്നാം കക്ഷി ബൗദ്ധിക സ്വത്തവകാശം ലംഘിക്കുന്ന ഉള്ളടക്കം സമർപ്പിക്കുക.';

  @override
  String get legalTermsProhibitedUseHeading => '5. നിരോധിത ഉപയോഗം';

  @override
  String get legalTermsRefundBody =>
      'അക്കൗണ്ട് ക്രമീകരണങ്ങളിൽ നിന്ന് നിങ്ങൾക്ക് എപ്പോൾ വേണമെങ്കിലും സബ്‌സ്‌ക്രിപ്‌ഷൻ റദ്ദാക്കാം. നിലവിലെ ബില്ലിംഗ് കാലയളവിൻ്റെ അവസാനത്തിൽ റദ്ദാക്കൽ പ്രാബല്യത്തിൽ വരും; ഉപയോഗിക്കാത്ത സമയത്തിന് ഭാഗികമായ റീഫണ്ടുകളൊന്നും നൽകുന്നില്ല. പിഴവാണ് നിങ്ങളിൽ നിന്ന് ഈടാക്കിയതെന്ന് നിങ്ങൾ വിശ്വസിക്കുന്നുവെങ്കിൽ, ചാർജ്ജ് ചെയ്ത് 30 ദിവസത്തിനകം support@odaflow.com-ൽ ബന്ധപ്പെടുക. ഞങ്ങൾ അവലോകനം ചെയ്യുകയും, ഉചിതമെങ്കിൽ, ഞങ്ങളുടെ വിവേചനാധികാരത്തിൽ ഒരു പ്രോ-റാറ്റ റീഫണ്ട് നൽകുകയും ചെയ്യും.';

  @override
  String get legalTermsRefundHeading => '8. റീഫണ്ടുകളും റദ്ദാക്കലും';

  @override
  String get legalTermsSeverabilityBody =>
      'ഈ നിബന്ധനകളിലെ ഏതെങ്കിലും വ്യവസ്ഥകൾ നടപ്പിലാക്കാൻ കഴിയില്ലെന്ന് കണ്ടെത്തിയാൽ, ശേഷിക്കുന്ന വ്യവസ്ഥകൾ പൂർണ്ണമായി തുടരും. ഒരു അവകാശവും നടപ്പിലാക്കുന്നതിൽ നമ്മുടെ പരാജയം ആ അവകാശത്തിൻ്റെ ഇളവ് അല്ല. ഈ നിബന്ധനകൾ, സ്വകാര്യതാ നയം, ഡാറ്റ & AI സമ്മത നയം എന്നിവയ്‌ക്കൊപ്പം പ്ലാറ്റ്‌ഫോമിനെ സംബന്ധിച്ച് നിങ്ങളും DVTech വെഞ്ച്വറുകളും തമ്മിലുള്ള മുഴുവൻ കരാറും രൂപീകരിക്കുന്നു.';

  @override
  String get legalTermsSeverabilityHeading => '19. ജനറൽ';

  @override
  String get legalTermsSubscriptionBody =>
      'പണമടച്ചുള്ള പ്ലാനുകൾ പ്രതിമാസ അല്ലെങ്കിൽ വാർഷിക സൈക്കിളിൽ മുൻകൂട്ടി ബിൽ ചെയ്യുന്നു. ചെക്ക്ഔട്ടിൽ വിലകൾ നിങ്ങളുടെ പ്രാദേശിക കറൻസിയിൽ പ്രദർശിപ്പിക്കും, ബാധകമായ നികുതികളും ഉൾപ്പെട്ടേക്കാം. പുതുക്കൽ തീയതിക്ക് മുമ്പ് നിങ്ങൾ റദ്ദാക്കുന്നില്ലെങ്കിൽ ഓരോ ബില്ലിംഗ് കാലയളവിൻ്റെ അവസാനത്തിലും സബ്‌സ്‌ക്രിപ്‌ഷനുകൾ സ്വയമേവ പുതുക്കും. പണമടയ്ക്കുന്നതിൽ പരാജയപ്പെടുന്നത് സസ്പെൻഷനോ ആക്സസ് അവസാനിപ്പിക്കുന്നതിനോ കാരണമായേക്കാം.';

