  @override
  String get legalTermsTrialBody =>
      'സൈൻ-അപ്പിൽ വ്യക്തമാക്കിയിട്ടുള്ള പുതിയ അക്കൗണ്ടുകൾക്ക് സൗജന്യ ട്രയലുകൾ ലഭ്യമാണ്. ട്രയൽ കാലയളവ് അവസാനിക്കുമ്പോൾ, ട്രയൽ അവസാനിക്കുന്നതിന് മുമ്പ് നിങ്ങൾ റദ്ദാക്കുന്നില്ലെങ്കിൽ, നിങ്ങളുടെ അക്കൗണ്ട് ബാധകമായ നിരക്കിൽ പണമടച്ചുള്ള സബ്‌സ്‌ക്രിപ്‌ഷനായി സ്വയമേവ പരിവർത്തനം ചെയ്യും. ട്രയൽ ഓഫറുകൾ എപ്പോൾ വേണമെങ്കിലും പരിഷ്‌ക്കരിക്കാനോ നിർത്താനോ ഉള്ള അവകാശം ഞങ്ങളിൽ നിക്ഷിപ്തമാണ്.';

