  @override
  String get legalTermsWarrantiesBody =>
      'ഞങ്ങൾ ഇത് ഉറപ്പുനൽകുന്നു: (എ) ഞങ്ങൾ പ്ലാറ്റ്‌ഫോമിന് ന്യായമായ വൈദഗ്ധ്യവും പരിചരണവും നൽകും; (ബി) വാണിജ്യപരമായി ന്യായമായ സുരക്ഷാ സമ്പ്രദായങ്ങൾ ഞങ്ങൾ നിലനിർത്തും. നിയമം അനുവദനീയമായ പരമാവധി, ഒരു പ്രത്യേക ആവശ്യത്തിനായി ഫിറ്റ്നസ് വാറൻ്റികളില്ലാതെ പ്ലാറ്റ്ഫോം \"ഉള്ളതുപോലെ\" നൽകിയിരിക്കുന്നു. AI ഔട്ട്‌പുട്ടുകളുടെ കൃത്യതയോ പൂർണ്ണതയോ കറൻസിയോ ഞങ്ങൾ ഉറപ്പുനൽകുന്നില്ല.';

